def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if lock:
                with lock:
                    if key in cache:
                        return cache[key]
                    else:
                        result = func(*args, **kwargs)
                        cache[key] = result
                        return result
            else:
                if key in cache:
                    return cache[key]
