def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        hits = misses = 0
        lock = threading.Lock()

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = (args, frozenset(kwargs.items())) if typed else args
            with lock:
                now = timer()
                try:
                    value, expire = cache[key]
                    if now < expire:
                        hits += 1
                        return value
                    else:
                        misses += 1
                except KeyError:
                    misses += 1
            value = func(*args, **kwargs)
            with lock:
                cache[key] = (value, now + ttl)
            return value

        def cache_info():
            with lock:
                return {
                    "hits": hits,
                    "misses": misses,
                    "maxsize": maxsize,
                    "size": len(cache),
                }

        wrapper.cache_info = cache_info
        return wrapper

    return decorator
