def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        queue = []
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            if typed and not isinstance(result, type(None)):
                result = type(result)
            cache[key] = result
            queue.append(key)
            if len(queue) > maxsize:
                del cache[queue.pop(0)]
            return result
        return wrapper
    return decorator
