def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if not resource.observer_schema:
            resource.observer_schema = generate_default_observer_schema_for_resource(resource)

def generate_default_observer_schema_for_resource(resource):
    """Generate the default observer schema for a Kubernetes resource.

    Args:
        resource (krake.data.kubernetes.Resource): The resource for which to generate a
            default observer schema
    """
    schema = {}
    for field in resource.fields:
        if field.observer_schema:
            schema[field.name] = field.observer_schema
        else:
            schema[field.name] = generate_default_observer_schema_for_field(field)
    return schema

def generate_default_observer_schema_for_field(field):
    """Generate the default observer schema for a Kubernetes field.

    Args:
        field (krake.data.kubernetes.Field): The field for which to generate a
            default observer schema
    """
    schema = {}
    if field.type == "string":
        schema["type"] = "string"
    elif field.type == "integer":
        schema["type"] = "integer"
    elif field.type == "boolean":
        schema["type"] = "boolean"
    elif field.type == "array":
        schema["type"] = "array"
        schema["items"] = generate_default_observer_schema_for_field(field.items)
    elif field.type == "object":
        schema["type"] = "object"
        schema["properties"] = {}
        for property in field.properties:
            schema["properties"][property.name] = generate_default_observer_schema_for_field(property)
    return schema

