def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check if the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check if the fixity block has the required keys
    required_keys = ["algorithm", "digest", "digest_type"]
    for key in required_keys:
        if key not in fixity:
            raise ValueError(f"Fixity block must contain the key {key}")

    # Check if the algorithm is a supported algorithm
    algorithm = fixity["algorithm"]
    if algorithm not in ["md5", "sha1", "sha256"]:
        raise ValueError(f"Unsupported algorithm: {algorithm}")

    # Check if the digest is a string
    digest = fixity["digest"]
    if not isinstance(digest, str):
        raise ValueError("Digest must be a string")

    # Check if the digest type is a string
    digest_type = fixity["digest_type"]
    if not isinstance(digest_type, str):
        raise ValueError("Digest type must be a string")

    # Check if the digest type is a supported digest type
    if digest_type not in ["hex", "base64"]:
        raise ValueError(f"Unsupported digest type: {digest_type}")

    # Check if the digest is a valid hex or base64 string
    if digest_type == "hex":
        if not re.match(r"^[0-9a-fA-F]+$", digest):
            raise ValueError("Digest must be a valid hex string")
    elif digest_type == "base64":
        if not re.match(r"^[A-Za-z0-9+/]+={0,2}$", digest):
            raise ValueError("Digest must be a valid base64 string")

    # Check if the manifest files are valid
    for file in manifest_files:
        if not isinstance(file, str):
            raise ValueError("Manifest files must be strings")
        if not os.path.isfile(file):
            raise ValueError(f"Manifest file {file} does not exist")

    # Check if the fixity block references only files listed in the manifest
    for file in fixity["files"]:
        if file not in manifest_files:
            raise ValueError(f"Fixity block references file {file} which is not listed in the manifest")

    # If all checks pass, return True
    return True

