def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        print("Pretty printing element " + self.id)
    result = ""
    if self.id:
        result += self.id + " "
    result += self.tag
    if self.attributes:
        result += " " + " ".join(["{}={}".format(k, v) for k, v in self.attributes.items()])
    if self.text:
        result += " " + self.text
    if self.children:
        result += "\n" + "  " * (indent + 1) + " ".join([c.pretty(indent + 1, debug) for c in self.children])
    return result

