def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list):
        raise ValueError("pieces must be a list of VersionPiece objects")
    if not isinstance(style, str):
        raise ValueError("style must be a string")

    # Check if the style is supported
    if style not in SUPPORTED_STYLES:
        raise ValueError("style must be one of the supported styles")

    # Render the pieces
    rendered_pieces = []
    for piece in pieces:
        if piece.type == "text":
            rendered_pieces.append(piece.text)
        elif piece.type == "entity":
            rendered_pieces.append(piece.entity.name)
        elif piece.type == "attribute":
            rendered_pieces.append(piece.attribute.name)
        else:
            raise ValueError("unsupported piece type")

    # Join the rendered pieces into a single string
    rendered_text = "".join(rendered_pieces)

    # Apply the style to the rendered text
    if style == "plain":
        return rendered_text
    elif style == "html":
        return "<html><body>" + rendered_text + "</body></html>"
    elif style == "markdown":
        return "**" + rendered_text + "**"
    else:
        raise ValueError("unsupported style")
