def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not isinstance(hist, Histogram):
        raise ValueError("hist must be a Histogram")
    if make_value is not None and not callable(make_value):
        raise ValueError("make_value must be a callable")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
    if not isinstance(field_names, tuple) or len(field_names) != 2:
        raise ValueError("field_names must be a tuple of length 2")
    if scale is not None and not isinstance(scale, bool):
        raise ValueError("scale must be a bool")

    graph = Graph()
    for bin_ in hist:
        if not isinstance(bin_, NumericBin):
            raise ValueError("hist must contain only numeric bins")
        if make_value is None:
            value = bin_.content
        else:
            value = make_value(bin_.content)
        if not isinstance(value, tuple) or len(value) != 2:
            raise ValueError("make_value must return a tuple of length 2")
        x = bin_.left if get_coordinate == "left" else bin_.right if get_coordinate == "right" else (bin_.left + bin_.right) / 2
        y = value[0]
        y_error = value[1]
        graph.add_point(x, y, y_error)

    if scale is not None:
        graph.scale = hist.scale if scale else None

    return graph
