def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Check if the cache is empty
    if len(self.cache) == 0:
        raise KeyError("Cache is empty")

    # Find the least frequently used key
    least_frequent_key = None
    least_frequent_value = None
    for key, value in self.cache.items():
        if least_frequent_key is None or value.frequency < least_frequent_value.frequency:
            least_frequent_key = key
            least_frequent_value = value

    # Remove the least frequently used key-value pair from the cache
    del self.cache[least_frequent_key]

    # Return the least frequently used key-value pair
    return (least_frequent_key, least_frequent_value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self.items:
        raise KeyError("Cache is empty")

