        root = ET.fromstring(document)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        xrd = root.find('xrd:XRD', ns)
        if xrd is None:
            raise ValueError('Invalid XRD format')
        webfinger = {}
        for subject in xrd.findall('xrd:Subject', ns):
            webfinger[subject.text] = {}
            for property in subject.findall('xrd:Property', ns):
                webfinger[subject.text][property.attrib['name']] = property.text
        return webfinger
    else:
        # Parse JSON format
        webfinger = json.loads(document)
        if 'subject' not in webfinger or 'aliases' not in webfinger or 'links' not in webfinger:
            raise ValueError('Invalid JSON format')
        return webfinger
```

