@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if not spec_content:
        raise IRValidatorException("Spec content is required")

    spec_data = yaml.safe_load(spec_content)

    if not spec_data:
        raise IRValidatorException("Spec content is empty")

    if "name" not in spec_data:
        raise IRValidatorException("Spec name is missing")

    if "version" not in spec_data:
        raise IRValidatorException("Spec version is missing")

    if "description" not in spec_data:
        raise IRValidatorException("Spec description is missing")

    if "inputs" not in spec_data:
        raise IRValidatorException("Spec inputs are missing")

    if "outputs" not in spec_data:
        raise IRValidatorException("Spec outputs are missing")

    if "components" not in spec_data:
        raise IRValidatorException("Spec components are missing")

    return spec_data
```

```
@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise ValueError("YAML file path is required")

    with open(yaml_file, "r") as f:
        data = yaml.safe_load(f)

    if not data:
        raise IRValidatorException("YAML file is empty")

    required_fields = ["name", "version", "description", "author", "license"]
    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Missing required field '{field}' in YAML file")

    return data
