def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        if not isinstance(parser_dict, dict):
            raise ValueError("parser_dict must be a dictionary")

        for key, value in parser_dict.items():
            if key == "include":
                if not isinstance(value, list):
                    raise ValueError("include must be a list")

                for include in value:
                    if not isinstance(include, str):
                        raise ValueError("include must be a string")

                    if include not in self.groups:
                        raise ValueError("include must be a valid group name")

                    self.groups[key].extend(self.groups[include])

        return self.groups

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    # Get the spec for this element
    spec = self.spec

    # Get the default values for the arguments
    default_values = {}
    for arg in spec.args:
        if arg.default is not None:
            default_values[arg.name] = arg.default

    # Get the default values for the keyword arguments
    default_values.update(spec.keywords)

    # Return the resolved default values
    return default_values

def get_deprecated_args(self):
        """Returning dict with options which deprecate others. """
        deprecated_args = {}
        for arg in self.args:
            if arg.deprecated:
                deprecated_args[arg.name] = arg.deprecated
        return deprecated_args

