def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    # Validate input parameters
    if not isinstance(ir_workspace, InfraredWorkspace):
        raise ValueError("ir_workspace must be an InfraredWorkspace object")
    if not isinstance(ir_plugin, InfraredPlugin):
        raise ValueError("ir_plugin must be an InfraredPlugin object")
    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a string")
    if verbose is not None and not isinstance(verbose, int):
        raise ValueError("verbose must be an integer or None")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("extra_vars must be a dict or None")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("ansible_args must be a dict or None")

    # Build the command line arguments
    args = ["ansible-playbook", playbook_path]
    if verbose is not None:
        args.append("-" + "v" * verbose)
    if extra_vars is not None:
        for key, value in extra_vars.items():
            args.append("-e")
            args.append(f"{key}={value}")
    if ansible_args is not None:
        for key, value in ansible_args.items():
            args.append("-" + key)
            args.append(value)

    # Run the command
    try:
        subprocess.run(args, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Ansible playbook failed with exit code {}".format(e.returncode))
```

